100	    }
101	
102	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
103	     *  separated by '@', none of which contain whitespace or a second '@'. */
104	    private static final java.util.regex.Pattern EMAIL_PATTERN =
105	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
106	
107	    /** Disposable email domains that are not accepted as an owner's email. */
108	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
109	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
110	
111	    /**
112	     * Normalize the optional email: absent stays absent; when present it must be syntactically
113	     * valid and is lower-cased. Returns {@code false} if present but invalid, including when its
114	     * domain is on the disposable-domain blocklist.
115	     */
116	    private boolean normalizeEmail(Owner owner) {
117	        String email = owner.getEmail();
118	        if (email == null || email.isEmpty()) {
119	            owner.setEmail(null);
120	            return true;
121	        }
122	        if (!EMAIL_PATTERN.matcher(email).matches()) {
123	            return false;
124	        }
125	        email = email.toLowerCase(java.util.Locale.ROOT);
126	        String domain = email.substring(email.indexOf('@') + 1);
127	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
128	            return false;
129	        }
130	        owner.setEmail(email);
131	        return true;
132	    }
133	
134	    /**
135	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
136	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
137	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
138	     *
139	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
140	     *         a valid E.164 number.
141	     */
142	    private static String toE164(String raw) {
143	        if (raw == null) {
144	            return null;
145	        }
146	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
147	        String digits;
148	        if (cleaned.startsWith("+")) {
149	            digits = cleaned.substring(1);
150	        } else {
151	            if (cleaned.startsWith("0")) {
152	                cleaned = cleaned.substring(1);
153	            }
154	            digits = "61" + cleaned;
155	        }
156	        if (!digits.matches("\\d{8,15}")) {
157	            return null;
158	        }
159	        return "+" + digits;
160	    }
161	
162	    /**
163	     * Validate the national-number length of a canonical E.164 string against its country code:
164	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
165	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
166	     * string produced by {@link #toE164}.
167	     *
168	     * @return {@code true} when the national-number length is correct for the country code.
169	     */
170	    private static boolean hasValidNationalLength(String e164) {
171	        String digits = e164.substring(1);
172	        if (digits.startsWith("61")) {
173	            return digits.length() - 2 == 9;
174	        }
175	        if (digits.startsWith("1")) {
176	            return digits.length() - 1 == 10;
177	        }
178	        return true;
179	    }
180	
181	    /**
182	     * Build the customer code {@code <REGION>-<HASH8>}: REGION is the region code derived from the
183	     * owner's postcode (NSW/VIC/QLD, or {@code UNKNOWN} when the postcode is absent or in no known
184	     * range) and HASH8 is the first 8 upper-case hex characters of SHA-256 over the concatenation of
185	     * the owner's normalized (E.164) telephone and last name (e.g. {@code NSW-3F9A0C17}). No sequence
186	     * numbers are used, so the base code is a pure function of the owner's region-and-hash identity.
187	     * When that base code collides with an existing owner's customerCode, {@code -<n>} is appended with
188	     * the smallest {@code n} of 2 or more that makes it unique, returning the de-duplicated code.
189	     */
190	    private String customerCodeFor(Owner owner) {
191	        String region = ownerMapper.regionFromPostcode(owner);
192	        if (region == null) {
193	            region = "UNKNOWN";
194	        }
195	        String base = region + "-" + hash8(owner.getTelephone(), owner.getLastName());
196	
197	        java.util.Set<String> existingCodes = new java.util.HashSet<>();
198	        for (Owner existing : this.clinicService.findAllOwners()) {
199	            String code = existing.getCustomerCode();
200	            if (code != null) {
201	                existingCodes.add(code);
202	            }
203	        }
204	        if (!existingCodes.contains(base)) {
205	            return base;
206	        }
207	        for (int n = 2; ; n++) {
208	            String candidate = base + "-" + n;
209	            if (!existingCodes.contains(candidate)) {
210	                return candidate;
211	            }
212	        }
213	    }
214	
215	    /**
216	     * First 8 upper-case hex characters (the first 4 bytes) of SHA-256 over
217	     * {@code normalizedTelephone + lastName}, treating a {@code null} component as empty.
218	     */
219	    private static String hash8(String normalizedTelephone, String lastName) {
220	        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
221	            + (lastName == null ? "" : lastName);
222	        try {
223	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
224	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
225	            StringBuilder sb = new StringBuilder(8);
226	            for (int i = 0; i < 4; i++) {
227	                sb.append(String.format("%02X", digest[i]));
228	            }
229	            return sb.toString();
230	        }
231	        catch (java.security.NoSuchAlgorithmException e) {
232	            throw new IllegalStateException(e);
233	        }
234	    }
235	
236	    /** Common street-type abbreviations expanded during address normalization. */
237	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
238	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
239	
240	    /**
241	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
242	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
243	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
244	     */
245	    private static String normalizeAddress(String value) {
246	        if (value == null) {
247	            return "";
248	        }
249	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
250	        if (collapsed.isEmpty()) {
251	            return "";
252	        }
253	        String[] tokens = collapsed.split(" ");
254	        StringBuilder sb = new StringBuilder(collapsed.length());
255	        for (int i = 0; i < tokens.length; i++) {
256	            if (i > 0) {
257	                sb.append(' ');
258	            }
259	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
260	        }
261	        return sb.toString();
262	    }
263	
264	    /**
265	     * Resolve and normalize the owner's postal address, preferring the structured form.
266	     *
267	     * <p>When a non-blank {@code addressLine1} is supplied the structured form is used: it, and the
268	     * optional {@code addressLine2}, are normalized in place and the composed address is the
269	     * normalized addressLine1 with a single space and the normalized addressLine2 appended when
270	     * addressLine2 is present. Otherwise the flat {@code address} input is normalized. Returns
271	     * {@code null} when neither form yields a non-empty address, so the caller can reject the
272	     * request.
273	     */
274	    private String composeAddress(Owner owner) {
275	        String line1 = owner.getAddressLine1();
276	        if (line1 != null && !line1.isBlank()) {
277	            String normalizedLine1 = normalizeAddress(line1);
278	            owner.setAddressLine1(normalizedLine1);
279	            String line2 = owner.getAddressLine2();
280	            if (line2 != null && !line2.isBlank()) {
281	                String normalizedLine2 = normalizeAddress(line2);
282	                owner.setAddressLine2(normalizedLine2);
283	                return normalizedLine1 + " " + normalizedLine2;
284	            }
285	            owner.setAddressLine2(null);
286	            return normalizedLine1.isEmpty() ? null : normalizedLine1;
287	        }
288	        String normalized = normalizeAddress(owner.getAddress());
289	        return normalized.isEmpty() ? null : normalized;
290	    }
291	
292	    /**
293	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
294	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
295	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
296	     */
297	    private static String normalizeForHousehold(String value) {
298	        if (value == null) {
299	            return "";
300	        }
301	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
302	    }
303	
304	    /**
305	     * Return the owners that already share this owner's household, i.e. resolve to the same
306	     * deterministic {@link #householdIdFor(Owner) householdId} (same normalized last name and
307	     * postcode).
308	     */
309	    private List<Owner> householdMembers(Owner owner) {
310	        String householdId = householdIdFor(owner);
311	        List<Owner> members = new java.util.ArrayList<>();
312	        for (Owner existing : this.clinicService.findAllOwners()) {
313	            if (householdId.equals(householdIdFor(existing))) {
314	                members.add(existing);
315	            }
316	        }
317	        return members;
318	    }
319	
320	    /**
321	     * Return {@code true} when another owner already shares this owner's household, i.e. resolves to
322	     * the same deterministic {@link #householdIdFor(Owner) householdId}.
323	     */
324	    private boolean sharesHouseholdWithExisting(Owner owner) {
325	        return !householdMembers(owner).isEmpty();
326	    }
327	
328	    /**
329	     * Count the existing owners that share this owner's first name and last name, compared
330	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
331	     */
332	    private int namesakeCount(Owner owner) {
333	        String firstName = owner.getFirstName();
334	        String lastName = owner.getLastName();
335	        int count = 0;
336	        for (Owner existing : this.clinicService.findAllOwners()) {
337	            if (firstName != null && lastName != null
338	                && firstName.equalsIgnoreCase(existing.getFirstName())
339	                && lastName.equalsIgnoreCase(existing.getLastName())) {
340	                count++;
341	            }
342	        }
343	        return count;
344	    }
345	
346	    /**
347	     * A stable, shared household identifier: the first 12 hex characters of SHA-256 over
348	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes an empty string).
349	     * Because it is a pure function of the last name and postcode, every owner in the same household
350	     * deterministically resolves to the same value.
351	     */
352	    private static String householdIdFor(Owner owner) {
353	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
354	        String key = normalizeForHousehold(owner.getLastName()) + "|" + postcode;
355	        try {
356	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
357	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
358	            StringBuilder sb = new StringBuilder(12);
359	            for (int i = 0; i < 6; i++) {
360	                sb.append(String.format("%02X", digest[i]));
361	            }
362	            return sb.toString();
363	        }
364	        catch (java.security.NoSuchAlgorithmException e) {
365	            throw new IllegalStateException(e);
366	        }
367	    }
368	
369	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
370	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
371	        "NSW", new int[] {2000, 2099},
372	        "VIC", new int[] {3000, 3099},
373	        "QLD", new int[] {4000, 4099});
374	
375	    /**
376	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
377	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
378	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
379	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
380	     * postcode.
381	     */
382	    private boolean isPostcodeValid(Owner owner) {
383	        String postcode = owner.getPostcode();
384	        if (postcode == null || postcode.isEmpty()) {
385	            return true;
386	        }
387	        if (!postcode.matches("\\d{4}")) {
388	            return false;
389	        }
390	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
391	        if (range == null) {
392	            return true;
393	        }
394	        int value = Integer.parseInt(postcode);
395	        return value >= range[0] && value <= range[1];
396	    }
397	
398	    /**
399	     * Find an existing owner that makes this (already known to be non-hard-duplicate) owner a
400	     * "possible duplicate": one that shares the owner's last name (case-insensitive) and postcode
401	     * but carries a different (normalized) telephone. When several match, the one with the smallest
402	     * id is chosen so the result is deterministic. Returns {@code null} when the owner has no
403	     * postcode or no such existing owner exists.
404	     */
405	    private Owner possibleDuplicateOf(Owner owner) {
406	        String lastName = owner.getLastName();
407	        String postcode = owner.getPostcode();
408	        String telephone = owner.getTelephone();
409	        if (lastName == null || postcode == null || postcode.isEmpty()) {
410	            return null;
411	        }
412	        Owner match = null;
413	        for (Owner existing : this.clinicService.findAllOwners()) {
414	            if (lastName.equalsIgnoreCase(existing.getLastName())
415	                && postcode.equals(existing.getPostcode())
416	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
417	                if (match == null || (existing.getId() != null && match.getId() != null
418	                    && existing.getId() < match.getId())) {
419	                    match = existing;
420	                }
421	            }
422	        }
423	        return match;
424	    }
425	
426	    /** Maximum number of owners permitted in a single city. */
427	    private static final int CITY_CAPACITY = 50;
428	
429	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
430	    private static final int DAILY_CREATE_LIMIT = 100;
431	
432	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
433	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
434	
435	    /**
436	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
437	     * Used to enforce the per-city capacity on create (before this owner is saved).
438	     */
439	    private int cityOwnerCount(Owner owner) {
440	        String city = owner.getCity();
441	        int count = 0;
442	        for (Owner existing : this.clinicService.findAllOwners()) {
443	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
444	                count++;
445	            }
446	        }
447	        return count;
448	    }
449	
450	    /**
451	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
452	     * following Monday, any weekday is returned unchanged. Applied to the effective registration date
453	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
454	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
455	     */
456	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
457	        switch (date.getDayOfWeek()) {
458	            case SATURDAY:
459	                return date.plusDays(2);
460	            case SUNDAY:
461	                return date.plusDays(1);
462	            default:
463	                return date;
464	        }
465	    }
466	
467	    /**
468	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
469	     * per-day create limit on create (before this owner is saved).
470	     */
471	    private int ownersRegisteredOn(java.time.LocalDate day) {
472	        int count = 0;
473	        for (Owner existing : this.clinicService.findAllOwners()) {
474	            if (day.equals(existing.getRegistrationDate())) {
475	                count++;
476	            }
477	        }
478	        return count;
479	    }
480	
481	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
482	    @Override
483	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
484	        HttpHeaders headers = new HttpHeaders();
485	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
486	        if (!isPostcodeValid(owner)) {
487	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
488	        }
489	        String telephone = toE164(owner.getTelephone());
490	        if (telephone == null || !hasValidNationalLength(telephone)) {
491	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
492	        }
493	        if (!normalizeEmail(owner)) {
494	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
495	        }
496	        String address = composeAddress(owner);
497	        if (address == null) {
498	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
499	        }
500	        owner.setAddress(address);
501	        owner.setTelephone(telephone);
502	        if (owner.getRegistrationDate() != null
503	            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
504	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
505	        }
506	        java.time.LocalDate registrationDate = toBusinessDay(
507	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
508	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
509	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
510	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
511	        }
512	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
513	            return new ResponseEntity<>(HttpStatus.CONFLICT);
514	        }
515	        // The householdId is deterministic (SHA-256 over normalized lastName + '|' + postcode), so
516	        // owners with the same last name and postcode automatically share it. The link is no longer
517	        // created by copying an existing owner's id around.
518	        owner.setHouseholdId(householdIdFor(owner));
519	        List<Owner> householdMembers = householdMembers(owner);
520	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
521	        boolean declaredHouseholdMember = sharesHousehold && !householdMembers.isEmpty();
522	
523	        // Hard duplicate: a new owner whose WHOLE identityKey (telephone|email|householdId) equals an
524	        // existing owner's is a byte-for-byte identity match and is always rejected.
525	        String identityKey = owner.getIdentityKey();
526	        for (Owner existing : this.clinicService.findAllOwners()) {
527	            if (identityKey.equals(existing.getIdentityKey())) {
528	                return new ResponseEntity<>(HttpStatus.CONFLICT);
529	            }
530	        }
531	        // Household duplicate: another owner already shares this (last name, postcode) household.
532	        // Rejected as a duplicate unless the caller sets 'sharesHousehold', which now only bypasses
533	        // this block (the shared householdId itself is already assigned deterministically above).
534	        if (!householdMembers.isEmpty() && !sharesHousehold) {
535	            return new ResponseEntity<>(HttpStatus.CONFLICT);
536	        }
537	        // A declared household member is not a suspected duplicate. Otherwise, flag an owner that
538	        // shares an existing owner's last name and postcode with a different telephone.
539	        if (declaredHouseholdMember) {
540	            owner.setPossibleDuplicate(false);
541	            owner.setPossibleDuplicateOf(null);
542	        }
543	        else {
544	            Owner duplicateOf = possibleDuplicateOf(owner);
545	            owner.setPossibleDuplicate(duplicateOf != null);
546	            owner.setPossibleDuplicateOf(duplicateOf == null ? null : duplicateOf.getId());
547	        }
548	        owner.setNamesakeCount(namesakeCount(owner));
549	        owner.setHouseholdSize(householdMembers.size() + 1);
550	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
551	        owner.setRegistrationDate(registrationDate);
552	        owner.setCustomerCode(customerCodeFor(owner));
553	        this.clinicService.saveOwner(owner);
554	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
555	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
556	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
557	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
558	        headers.setLocation(UriComponentsBuilder.newInstance()
559	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
560	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
561	    }
562	
563	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
564	    @Override
565	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
566	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
567	        if (currentOwner == null) {
568	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
569	        }
570	        currentOwner.setAddress(ownerFieldsDto.getAddress());
571	        currentOwner.setCity(ownerFieldsDto.getCity());
572	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
573	        currentOwner.setLastName(ownerFieldsDto.getLastName());
574	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
575	        currentOwner.setEmail(ownerFieldsDto.getEmail());
576	        if (!normalizeEmail(currentOwner)) {
577	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
578	        }
579	        this.clinicService.saveOwner(currentOwner);
580	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
581	    }
582	
583	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
584	    @Transactional
585	    @Override
586	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
587	        Owner owner = this.clinicService.findOwnerById(ownerId);
588	        if (owner == null) {
589	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
590	        }
591	        this.clinicService.deleteOwner(owner);
592	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
593	    }
594	
595	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
596	    @Override
597	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
598	        Owner owner = this.clinicService.findOwnerById(ownerId);
599	        if (owner == null) {
600	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
601	        }
602	        HttpHeaders headers = new HttpHeaders();
603	        Pet pet = petMapper.toPet(petFieldsDto);
604	        owner.setId(ownerId);
605	        pet.setOwner(owner);
606	        pet.getType().setName(null);
607	        this.clinicService.savePet(pet);
608	        PetDto petDto = petMapper.toPetDto(pet);
609	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
610	            .buildAndExpand(pet.getId()).toUri());
611	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
612	    }
613	
614	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
615	    @Override
616	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
617	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
618	        if (currentOwner != null) {
619	            Pet currentPet = this.clinicService.findPetById(petId);
620	            if (currentPet != null) {
621	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
622	                currentPet.setName(petFieldsDto.getName());
623	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
624	                this.clinicService.savePet(currentPet);
625	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
626	            }
627	        }
628	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
629	    }
630	
631	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
632	    @Override
633	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
634	        HttpHeaders headers = new HttpHeaders();
635	        Visit visit = visitMapper.toVisit(visitFieldsDto);
636	        Pet pet = new Pet();
637	        pet.setId(petId);
638	        visit.setPet(pet);
639	        this.clinicService.saveVisit(visit);
640	        VisitDto visitDto = visitMapper.toVisitDto(visit);
641	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
642	            .buildAndExpand(visit.getId()).toUri());
643	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
644	    }
645	
646	
647	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
648	    @Override
649	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
650	        Owner owner = this.clinicService.findOwnerById(ownerId);
651	        if (owner != null) {
652	            Pet pet = owner.getPet(petId);
653	            if (pet != null) {
654	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
655	            }
656	        }
657	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
658	    }
659	}
