34	    /**
35	     * Formats the stored E.164 {@code telephone} for humans: the {@code '+'} and country code, a
36	     * space, then the national digits grouped in threes (e.g. {@code +61412345678} -&gt;
37	     * {@code +61 412 345 678}). The country code is taken as {@code 61} (Australia) or {@code 1}
38	     * (NANP) when recognised, otherwise a single leading digit. Returns {@code null} when the
39	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164
40	     * number.
41	     */
42	    default String telephoneDisplay(Owner owner) {
43	        String telephone = owner.getTelephone();
44	        if (telephone == null || telephone.isEmpty()) {
45	            return null;
46	        }
47	        if (!telephone.startsWith("+") || !telephone.substring(1).matches("\\d+")) {
48	            return telephone;
49	        }
50	        String digits = telephone.substring(1);
51	        int countryCodeLength;
52	        if (digits.startsWith("61")) {
53	            countryCodeLength = 2;
54	        }
55	        else if (digits.startsWith("1")) {
56	            countryCodeLength = 1;
57	        }
58	        else {
59	            countryCodeLength = 1;
60	        }
61	        String countryCode = digits.substring(0, countryCodeLength);
62	        String national = digits.substring(countryCodeLength);
63	        StringBuilder grouped = new StringBuilder();
64	        for (int i = 0; i < national.length(); i++) {
65	            if (i > 0 && i % 3 == 0) {
66	                grouped.append(' ');
67	            }
68	            grouped.append(national.charAt(i));
69	        }
70	        return "+" + countryCode + (national.isEmpty() ? "" : " " + grouped);
71	    }
72	
73	    /**
