84	        java.time.LocalDate reference = owner.getRegistrationDate() != null
85	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
86	        int age = java.time.Period.between(birthDate, reference).getYears();
87	        if (age < 18) {
88	            return OwnerDto.AgeBandEnum.MINOR;
89	        }
90	        if (age < 65) {
91	            return OwnerDto.AgeBandEnum.ADULT;
92	        }
93	        return OwnerDto.AgeBandEnum.SENIOR;
94	    }
