97	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is
98	     * present, otherwise {@code PHONE}.
99	     */
100	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
101	        String email = owner.getEmail();
102	        if (email != null && !email.isEmpty()) {
103	            return OwnerDto.ContactPreferenceEnum.EMAIL;
104	        }
105	        return OwnerDto.ContactPreferenceEnum.PHONE;
106	    }
107	
108	    /**
109	     * Derives the owner's locality (region) from the region-and-hash identity: it is the
110	     * {@code <REGION>} segment of the customerCode ({@code <REGION>-<HASH8>}), i.e. the region
111	     * derived from the postcode at create time. When the customerCode is absent or malformed
112	     * (e.g. legacy records), it falls back to the postcode range and then the fixed city-to-region
113	     * table, returning {@code UNKNOWN} when neither source resolves.
