260	     * where YY is the last two digits of the registrationDate year. Returns {@code null}
261	     * when either source field is absent.
262	     */
263	    default String membershipNumber(Owner owner) {
264	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
265	            return null;
