273	     * owner's customerCode. Non-digit characters are ignored. Returns {@code null}
274	     * when the customerCode is absent.
275	     */
276	    default Integer checkDigit(Owner owner) {
277	        String customerCode = owner.getCustomerCode();
278	        if (customerCode == null) {
279	            return null;
280	        }
281	        int sum = 0;
282	        boolean dbl = true;
283	        for (int i = customerCode.length() - 1; i >= 0; i--) {
284	            char c = customerCode.charAt(i);
285	            if (c < '0' || c > '9') {
286	                continue;
287	            }
288	            int d = c - '0';
289	            if (dbl) {
290	                d *= 2;
